package com.arantec.castafiore.ui.fragments

import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.content.ServiceConnection
import android.os.Bundle
import android.os.IBinder
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.recyclerview.widget.LinearLayoutManager
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.databinding.FragmentFavoritesBinding
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.ui.adapters.SongAdapter

class FavoritesFragment : Fragment() {

    private var _binding: FragmentFavoritesBinding? = null
    private val binding get() = _binding!!

    private lateinit var musicRepository: MusicRepository
    private lateinit var songAdapter: SongAdapter
    private var musicService: MusicService? = null
    private var isBound = false

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as MusicService.MusicBinder
            musicService = binder.getService()
            isBound = true
        }

        override fun onServiceDisconnected(name: ComponentName?) {
            musicService = null
            isBound = false
        }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        _binding = FragmentFavoritesBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())
        setupRecyclerView()
        bindMusicService()
        loadFavorites()
    }

    private fun setupRecyclerView() {
        songAdapter = SongAdapter(
            onSongClick = { song, position ->
                playSong(song)
            },
            onSongMoreClick = { song ->
                showSongOptions(song)
            }
        )

        binding.recyclerView.apply {
            layoutManager = LinearLayoutManager(context)
            adapter = songAdapter
        }
    }

    private fun bindMusicService() {
        val intent = Intent(requireContext(), MusicService::class.java)
        requireContext().bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
    }

    private fun playSong(song: Song) {
        if (isBound && musicService != null) {
            musicService?.playSong(song)
        }
    }

    private fun loadFavorites() {
        // Por ahora mostraremos un mensaje vacío
        // TODO: Implementar sistema de favoritos con base de datos local
        binding.progressBar.visibility = View.GONE
        binding.tvEmpty.text = "Aún no tienes canciones favoritas\n\n" +
                "Próximamente podrás marcar canciones como favoritas y accederlas desde aquí."
        binding.tvEmpty.visibility = View.VISIBLE
    }

    private fun showSongOptions(song: Song) {
        // TODO: Implementar menú de opciones para la canción
    }

    override fun onDestroy() {
        super.onDestroy()
        if (isBound) {
            requireContext().unbindService(serviceConnection)
            isBound = false
        }
        _binding = null
    }
}

package com.arantec.castafiore.ui.fragments

import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.content.ServiceConnection
import android.os.Bundle
import android.os.IBinder
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.databinding.FragmentFavoritesBinding
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.ui.adapters.SongAdapter
import kotlinx.coroutines.launch

class FavoritesFragment : Fragment() {

    private var _binding: FragmentFavoritesBinding? = null
    private val binding get() = _binding!!

    private lateinit var musicRepository: MusicRepository
    private lateinit var songAdapter: SongAdapter
    private var musicService: MusicService? = null
    private var isBound = false

    private val favoriteSongs = mutableListOf<Song>()
    private var isPlaying = false

    private var playbackStateListener: ((Boolean) -> Unit)? = null
    private var songChangeListener: ((Song?) -> Unit)? = null

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as MusicService.MusicBinder
            musicService = binder.getService()
            isBound = true
            setupMusicServiceListeners()
            // Estado inicial
            isPlaying = musicService?.isPlaying() == true && isFavoritesQueuePlaying()
            updatePlayButton()
            songAdapter.setPlayingSong(musicService?.getCurrentSong()?.id)
        }

        override fun onServiceDisconnected(name: ComponentName?) {
            cleanupListeners()
            musicService = null
            isBound = false
        }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        _binding = FragmentFavoritesBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())

        setupToolbar()
        setupRecyclerView()
        bindMusicService()
        loadFavorites()
        setupFab()
    }

    private fun setupToolbar() {
        binding.toolbar.setNavigationOnClickListener {
            findNavController().popBackStack()
        }
        // Fondo estático oscuro para mantener coherencia con AlbumDetail
        binding.gradientBackground.setBackgroundColor(0xFF121212.toInt())
    }

    private fun setupRecyclerView() {
        songAdapter = SongAdapter(
            onSongClick = { _, position ->
                if (favoriteSongs.isNotEmpty()) {
                    musicService?.playQueue(favoriteSongs, position)
                }
            },
            onSongMoreClick = { song ->
                showSongOptions(song)
            }
        )

        binding.rvSongs.apply {
            layoutManager = LinearLayoutManager(context)
            adapter = songAdapter
            isNestedScrollingEnabled = false
        }
    }

    private fun setupFab() {
        binding.fabPlay.setOnClickListener {
            val service = musicService ?: return@setOnClickListener
            if (isFavoritesQueuePlaying()) {
                if (service.isPlaying()) service.pause() else service.play()
            } else if (favoriteSongs.isNotEmpty()) {
                service.playQueue(favoriteSongs, 0)
            }
        }
    }

    private fun bindMusicService() {
        val intent = Intent(requireContext(), MusicService::class.java)
        requireContext().bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
    }

    private fun loadFavorites() {
        binding.progressBar.visibility = View.VISIBLE
        binding.emptyLayout.visibility = View.GONE
        binding.rvSongs.visibility = View.GONE

        viewLifecycleOwner.lifecycleScope.launch {
            musicRepository.getStarredSongs().fold(
                onSuccess = { songs ->
                    favoriteSongs.clear()
                    favoriteSongs.addAll(songs)
                    songAdapter.updateSongs(favoriteSongs)

                    // Info header
                    binding.tvTitle.text = getString(R.string.favorite_songs_title)
                    binding.tvInfo.text = buildInfoText(favoriteSongs)

                    binding.progressBar.visibility = View.GONE
                    if (favoriteSongs.isEmpty()) {
                        binding.emptyLayout.visibility = View.VISIBLE
                    } else {
                        binding.rvSongs.visibility = View.VISIBLE
                    }

                    // Actualizar botón play según estado actual
                    isPlaying = musicService?.isPlaying() == true && isFavoritesQueuePlaying()
                    updatePlayButton()
                },
                onFailure = {
                    binding.progressBar.visibility = View.GONE
                    binding.emptyLayout.visibility = View.VISIBLE
                    binding.tvEmpty.text = getString(R.string.error_loading_favorites)
                }
            )
        }
    }

    private fun buildInfoText(list: List<Song>): String {
        val count = list.size
        val totalSeconds = list.sumOf { it.duration }
        val minutes = totalSeconds / 60
        val hours = minutes / 60
        val remMin = minutes % 60
        val durationText = if (hours > 0) "$hours h ${remMin} min" else "${minutes} min"
        return "$count canciones • $durationText"
    }

    private fun isFavoritesQueuePlaying(): Boolean {
        val current = musicService?.getCurrentSong() ?: return false
        return favoriteSongs.any { it.id == current.id }
    }

    private fun setupMusicServiceListeners() {
        musicService?.let { service ->
            cleanupListeners()

            playbackStateListener = { playing ->
                if (isAdded && _binding != null) {
                    requireActivity().runOnUiThread {
                        isPlaying = playing && isFavoritesQueuePlaying()
                        updatePlayButton()
                    }
                }
            }

            songChangeListener = { song ->
                if (isAdded && _binding != null) {
                    requireActivity().runOnUiThread {
                        isPlaying = service.isPlaying() && isFavoritesQueuePlaying()
                        updatePlayButton()
                        songAdapter.setPlayingSong(song?.id)
                    }
                }
            }

            playbackStateListener?.let { service.addPlaybackStateListener(it) }
            songChangeListener?.let { service.addSongChangeListener(it) }
        }
    }

    private fun cleanupListeners() {
        musicService?.let { service ->
            playbackStateListener?.let { service.removePlaybackStateListener(it) }
            songChangeListener?.let { service.removeSongChangeListener(it) }
        }
        playbackStateListener = null
        songChangeListener = null
    }

    private fun updatePlayButton() {
        if (!isAdded || _binding == null) return
        if (Thread.currentThread() == requireActivity().mainLooper.thread) {
            binding.fabPlay.setImageResource(if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play)
        } else {
            requireActivity().runOnUiThread {
                if (isAdded && _binding != null) {
                    binding.fabPlay.setImageResource(if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play)
                }
            }
        }
    }

    private fun showSongOptions(song: Song) {
        val bottomSheet = com.arantec.castafiore.ui.dialogs.SongOptionsBottomSheet
            .newInstance(song, false)
            .setOnDownloadClickListener { selectedSong ->
                val downloadManager = com.arantec.castafiore.data.download.SongDownloadManager.getInstance(requireContext())
                when {
                    downloadManager.isSongDownloaded(selectedSong.id) -> {
                        android.widget.Toast.makeText(requireContext(), getString(R.string.song_already_downloaded), android.widget.Toast.LENGTH_SHORT).show()
                    }
                    downloadManager.isSongDownloading(selectedSong.id) -> {
                        downloadManager.cancelDownload(selectedSong.id)
                        android.widget.Toast.makeText(requireContext(), getString(R.string.download_canceled, selectedSong.title), android.widget.Toast.LENGTH_SHORT).show()
                    }
                    else -> {
                        downloadManager.downloadSong(selectedSong)
                        android.widget.Toast.makeText(requireContext(), getString(R.string.download_started, selectedSong.title), android.widget.Toast.LENGTH_SHORT).show()
                    }
                }
            }
            .setOnDeleteDownloadClickListener { selectedSong ->
                val downloadManager = com.arantec.castafiore.data.download.SongDownloadManager.getInstance(requireContext())
                if (downloadManager.isSongDownloaded(selectedSong.id)) {
                    val builder = android.app.AlertDialog.Builder(requireContext())
                    builder.setTitle(R.string.delete_download)
                    builder.setMessage(getString(R.string.delete_download_confirm, selectedSong.title))
                    builder.setPositiveButton(R.string.delete) { dialogInterface: android.content.DialogInterface, _: Int ->
                        val success = downloadManager.deleteSong(selectedSong.id)
                        val msg = if (success) R.string.download_deleted else R.string.download_delete_error
                        android.widget.Toast.makeText(requireContext(), getString(msg), android.widget.Toast.LENGTH_SHORT).show()
                    }
                    builder.setNegativeButton(R.string.cancel, null)
                    builder.show()
                } else {
                    android.widget.Toast.makeText(requireContext(), getString(R.string.song_not_downloaded), android.widget.Toast.LENGTH_SHORT).show()
                }
            }
        bottomSheet.show(parentFragmentManager, "SongOptionsBottomSheet")
    }

    override fun onDestroy() {
        super.onDestroy()
        cleanupListeners()
        if (isBound) {
            requireContext().unbindService(serviceConnection)
            isBound = false
        }
        _binding = null
    }
}

package com.arantec.castafiore.ui.fragments

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.launch
import com.arantec.castafiore.R
import com.arantec.castafiore.databinding.FragmentLibraryBinding
import com.arantec.castafiore.ui.adapters.LibraryAdapter
import com.arantec.castafiore.data.models.LibraryItem
import com.arantec.castafiore.data.models.LibraryItemType
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Playlist
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.utils.ImageLoader
import com.google.android.material.chip.Chip

class LibraryFragment : Fragment() {

    private var _binding: FragmentLibraryBinding? = null
    private val binding get() = _binding!!

    private lateinit var libraryAdapter: LibraryAdapter
    private lateinit var musicRepository: MusicRepository
    private var currentFilter = "all"

    // Listas de datos separadas por tipo
    private var allItems = mutableListOf<LibraryItem>()
    private var playlists = mutableListOf<LibraryItem>()
    private var albums = mutableListOf<LibraryItem>()
    private var artists = mutableListOf<LibraryItem>()

    // Mapas para mantener referencias a los objetos completos
    private var albumsMap = mutableMapOf<String, Album>()
    private var playlistsMap = mutableMapOf<String, Playlist>()

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentLibraryBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())

        setupRecyclerView()
        setupFilters()
        setupControls()

        // Establecer estado inicial de los chips
        updateChipColors()

        loadInitialData()
    }

    private fun setupRecyclerView() {
        libraryAdapter = LibraryAdapter { item ->
            handleItemClick(item)
        }

        binding.rvLibraryItems.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = libraryAdapter
        }
    }

    private fun setupFilters() {
        // Configurar chips de filtros con manejo mejorado
        binding.chipAll.setOnClickListener {
            if (!binding.chipAll.isChecked) {
                selectChip(binding.chipAll, "all")
            }
        }

        binding.chipPlaylists.setOnClickListener {
            if (!binding.chipPlaylists.isChecked) {
                selectChip(binding.chipPlaylists, "playlists")
            }
        }

        binding.chipAlbums.setOnClickListener {
            if (!binding.chipAlbums.isChecked) {
                selectChip(binding.chipAlbums, "albums")
            }
        }

        binding.chipArtists.setOnClickListener {
            if (!binding.chipArtists.isChecked) {
                selectChip(binding.chipArtists, "artists")
            }
        }
    }

    private fun selectChip(selectedChip: Chip, filter: String) {
        // Desmarcar todos los chips sin disparar listeners
        val chips = listOf(binding.chipAll, binding.chipPlaylists, binding.chipAlbums, binding.chipArtists)
        chips.forEach { chip ->
            chip.isChecked = false
        }

        // Marcar el chip seleccionado
        selectedChip.isChecked = true

        // Aplicar filtro
        currentFilter = filter
        filterContent()

        // Actualizar colores visuales
        updateChipColors()
    }

    private fun updateChipColors() {
        val primaryColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.primary)
        val onSurfaceColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.on_surface)
        val outlineColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.outline)

        val chips = listOf(
            binding.chipAll,
            binding.chipPlaylists,
            binding.chipAlbums,
            binding.chipArtists
        )

        chips.forEach { chip ->
            if (chip.isChecked) {
                // Chip seleccionado - color principal (#FF2D55)
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT)
                chip.setTextColor(primaryColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(primaryColor)
                chip.chipStrokeWidth = 2f
                chip.isChipIconVisible = false
            } else {
                // Chip no seleccionado - colores por defecto
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT)
                chip.setTextColor(onSurfaceColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(outlineColor)
                chip.chipStrokeWidth = 1f
                chip.isChipIconVisible = false
            }
        }
    }

    private fun setupControls() {
        binding.tvSortBy.setOnClickListener {
            // TODO: Mostrar opciones de ordenamiento
        }

        binding.btnViewMode.setOnClickListener {
            // TODO: Cambiar entre vista lista y cuadrícula
        }

        binding.btnCreatePlaylist.setOnClickListener {
            // TODO: Crear nueva playlist
        }
    }

    private fun loadInitialData() {
        showLoading(true)

        lifecycleScope.launch {
            try {
                // Cargar datos por separado
                loadPlaylists()
                loadAlbums()
                loadArtists()

                // Una vez cargado todo, construir lista completa y mostrar contenido
                buildAllItemsList()
                filterContent()

            } catch (e: Exception) {
                showError("Error al cargar la biblioteca: ${e.message}")
            } finally {
                showLoading(false)
            }
        }
    }

    private suspend fun loadPlaylists() {
        try {
            playlists.clear()

            // Siempre agregar "Canciones que te gustan" primero
            playlists.add(
                LibraryItem(
                    id = "liked_songs",
                    title = "Canciones que te gustan",
                    subtitle = "Playlist • Tus favoritas",
                    imageUrl = null,
                    type = LibraryItemType.LIKED_SONGS
                )
            )

            // Luego cargar las playlists de la API
            val result = musicRepository.getPlaylists()
            result.onSuccess { playlistsFromApi ->
                playlistsFromApi.forEach { playlist ->
                    val subtitle = "${playlist.songCount ?: 0} canciones"

                    // Construir URL de imagen si la playlist tiene coverArt
                    var imageUrl: String? = null
                    if (playlist.coverArt != null) {
                        val (username, token, salt) = musicRepository.getAuthParams()
                        imageUrl = playlist.getCoverArtUrl(
                            musicRepository.serverUrl!!,
                            username,
                            token,
                            salt,
                            200
                        )
                    }

                    playlists.add(
                        LibraryItem(
                            id = playlist.id,
                            title = playlist.name,
                            subtitle = "Playlist • $subtitle",
                            imageUrl = imageUrl,
                            type = LibraryItemType.PLAYLIST
                        )
                    )

                    // Agregar al mapa de playlists
                    playlistsMap[playlist.id] = playlist
                }
            }.onFailure {
                // Si falla la API, al menos tenemos "Canciones que te gustan"
            }
        } catch (e: Exception) {
            // En caso de error, solo mantener "Canciones que te gustan"
            playlists.clear()
            playlists.add(
                LibraryItem(
                    id = "liked_songs",
                    title = "Canciones que te gustan",
                    subtitle = "Playlist • Tus favoritas",
                    imageUrl = null,
                    type = LibraryItemType.LIKED_SONGS
                )
            )
        }
    }

    private suspend fun loadAlbums() {
        try {
            val result = musicRepository.getStarredAlbums()
            result.onSuccess { albumsFromApi ->
                albums.clear()

                albumsFromApi.forEach { album ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildCoverArtUrl(
                        musicRepository.serverUrl!!,
                        album.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    albums.add(
                        LibraryItem(
                            id = album.id,
                            title = album.name,
                            subtitle = "Álbum • ${album.artist}",
                            imageUrl = imageUrl,
                            type = LibraryItemType.ALBUM
                        )
                    )

                    // Agregar al mapa de álbumes
                    albumsMap[album.id] = album
                }
            }.onFailure {
                albums.clear()
            }
        } catch (e: Exception) {
            albums.clear()
        }
    }

    private suspend fun loadArtists() {
        try {
            val result = musicRepository.getStarredArtists()
            result.onSuccess { artistsFromApi ->
                artists.clear()

                artistsFromApi.forEach { artist ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildArtistImageUrl(
                        musicRepository.serverUrl!!,
                        artist.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    // Construir subtítulo basado en si albumCount está disponible
                    val subtitle = if (artist.albumCount != null && artist.albumCount > 0) {
                        "Artista • ${artist.albumCount} álbumes"
                    } else {
                        "Artista"
                    }

                    artists.add(
                        LibraryItem(
                            id = artist.id,
                            title = artist.name,
                            subtitle = subtitle,
                            imageUrl = imageUrl,
                            type = LibraryItemType.ARTIST
                        )
                    )
                }
            }.onFailure {
                artists.clear()
            }
        } catch (e: Exception) {
            artists.clear()
        }
    }

    private fun buildAllItemsList() {
        allItems.clear()

        // Agregar en orden: playlists, álbumes, artistas
        allItems.addAll(playlists)
        allItems.addAll(albums)
        allItems.addAll(artists)
    }

    private fun filterContent() {
        val filteredItems = when (currentFilter) {
            "all" -> allItems.toList()
            "playlists" -> playlists.toList()
            "albums" -> albums.toList()
            "artists" -> artists.toList()
            else -> allItems.toList()
        }

        if (filteredItems.isEmpty()) {
            showEmptyState()
        } else {
            hideEmptyState()
            libraryAdapter.updateItems(filteredItems)
        }
    }

    private fun handleItemClick(item: LibraryItem) {
        when (item.type) {
            LibraryItemType.PLAYLIST -> {
                // Navegar a playlist específica
                val playlist = playlistsMap[item.id]
                if (playlist != null) {
                    val bundle = Bundle().apply {
                        putString("playlistId", playlist.id)
                        putString("playlistName", playlist.name)
                    }
                    // TODO: Verificar si existe playlistDetailFragment en navigation graph
                    // findNavController().navigate(R.id.playlistDetailFragment, bundle)
                }
            }
            LibraryItemType.ARTIST -> {
                val bundle = Bundle().apply {
                    putString("artistId", item.id)
                    putString("artistName", item.title)
                }
                findNavController().navigate(R.id.artistDetailFragment, bundle)
            }
            LibraryItemType.ALBUM -> {
                // Navegar a detalle de álbum usando el mismo patrón que artistas
                val album = albumsMap[item.id]
                if (album != null) {
                    val bundle = Bundle().apply {
                        putParcelable("album", album)
                    }
                    findNavController().navigate(R.id.albumDetailFragment, bundle)
                }
            }
            LibraryItemType.LIKED_SONGS -> {
                // Navegar a canciones favoritas
                findNavController().navigate(R.id.favoritesFragment)
            }
        }
    }

    private fun showLoading(show: Boolean) {
        binding.progressBar.visibility = if (show) View.VISIBLE else View.GONE
        binding.rvLibraryItems.visibility = if (show) View.GONE else View.VISIBLE
    }

    private fun showError(message: String) {
        binding.layoutEmpty.visibility = View.VISIBLE
        binding.rvLibraryItems.visibility = View.GONE
        // TODO: Mostrar mensaje de error específico
    }

    private fun showEmptyState() {
        binding.rvLibraryItems.visibility = View.GONE
        binding.layoutEmpty.visibility = View.VISIBLE
    }

    private fun hideEmptyState() {
        binding.layoutEmpty.visibility = View.GONE
        binding.rvLibraryItems.visibility = View.VISIBLE
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.arantec.castafiore.ui.fragments

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.launch
import com.arantec.castafiore.R
import com.arantec.castafiore.databinding.FragmentLibraryBinding
import com.arantec.castafiore.ui.adapters.LibraryAdapter
import com.arantec.castafiore.data.models.LibraryItem
import com.arantec.castafiore.data.models.LibraryItemType
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Playlist
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.utils.ImageLoader
import com.google.android.material.chip.Chip

class LibraryFragment : Fragment() {

    private var _binding: FragmentLibraryBinding? = null
    private val binding get() = _binding!!

    private lateinit var libraryAdapter: LibraryAdapter
    private lateinit var musicRepository: MusicRepository
    private var currentFilter = "all"

    // Listas de datos separadas por tipo
    private var allItems = mutableListOf<LibraryItem>()
    private var playlists = mutableListOf<LibraryItem>()
    private var albums = mutableListOf<LibraryItem>()
    private var artists = mutableListOf<LibraryItem>()

    // Mapas para mantener referencias a los objetos completos
    private var albumsMap = mutableMapOf<String, Album>()
    private var playlistsMap = mutableMapOf<String, Playlist>()

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentLibraryBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())

        setupRecyclerView()
        setupFilters()
        setupControls()

        // Establecer estado inicial de los chips
        updateChipColors()

        loadInitialData()
    }

    private fun setupRecyclerView() {
        libraryAdapter = LibraryAdapter { item ->
            handleItemClick(item)
        }

        binding.rvLibraryItems.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = libraryAdapter
        }
    }

    private fun setupFilters() {
        // Configurar chips de filtros con manejo mejorado
        binding.chipAll.setOnClickListener {
            if (!binding.chipAll.isChecked) {
                selectChip(binding.chipAll, "all")
            }
        }

        binding.chipPlaylists.setOnClickListener {
            if (!binding.chipPlaylists.isChecked) {
                selectChip(binding.chipPlaylists, "playlists")
            }
        }

        binding.chipAlbums.setOnClickListener {
            if (!binding.chipAlbums.isChecked) {
                selectChip(binding.chipAlbums, "albums")
            }
        }

        binding.chipArtists.setOnClickListener {
            if (!binding.chipArtists.isChecked) {
                selectChip(binding.chipArtists, "artists")
            }
        }
    }

    private fun selectChip(selectedChip: Chip, filter: String) {
        // Desmarcar todos los chips sin disparar listeners
        val chips = listOf(binding.chipAll, binding.chipPlaylists, binding.chipAlbums, binding.chipArtists)
        chips.forEach { chip ->
            chip.isChecked = false
        }

        // Marcar el chip seleccionado
        selectedChip.isChecked = true

        // Aplicar filtro
        currentFilter = filter
        filterContent()

        // Actualizar colores visuales
        updateChipColors()
    }

    private fun updateChipColors() {
        val primaryColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.primary)
        val onSurfaceColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.on_surface)
        val outlineColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.outline)

        val chips = listOf(
            binding.chipAll,
            binding.chipPlaylists,
            binding.chipAlbums,
            binding.chipArtists
        )

        chips.forEach { chip ->
            if (chip.isChecked) {
                // Chip seleccionado - color principal (#FF2D55)
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT)
                chip.setTextColor(primaryColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(primaryColor)
                chip.chipStrokeWidth = 2f
                chip.isChipIconVisible = false
            } else {
                // Chip no seleccionado - colores por defecto
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT)
                chip.setTextColor(onSurfaceColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(outlineColor)
                chip.chipStrokeWidth = 1f
                chip.isChipIconVisible = false
            }
        }
    }

    private fun setupControls() {
        binding.tvSortBy.setOnClickListener {
            // TODO: Mostrar opciones de ordenamiento
        }

        binding.btnViewMode.setOnClickListener {
            // TODO: Cambiar entre vista lista y cuadrícula
        }

        binding.btnCreatePlaylist.setOnClickListener {
            // TODO: Crear nueva playlist
        }
    }

    private fun loadInitialData() {
        showLoading(true)

        lifecycleScope.launch {
            try {
                // Cargar datos por separado
                loadPlaylists()
                loadAlbums()
                loadArtists()

                // Una vez cargado todo, construir lista completa y mostrar contenido
                buildAllItemsList()
                filterContent()

            } catch (e: Exception) {
                showError("Error al cargar la biblioteca: ${e.message}")
            } finally {
                showLoading(false)
            }
        }
    }

    private suspend fun loadPlaylists() {
        try {
            playlists.clear()

            // Siempre agregar "Canciones que te gustan" primero
            playlists.add(
                LibraryItem(
                    id = "liked_songs",
                    title = "Canciones que te gustan",
                    subtitle = "Playlist • Tus favoritas",
                    imageUrl = null,
                    type = LibraryItemType.LIKED_SONGS
                )
            )

            // Luego cargar las playlists de la API
            val result = musicRepository.getPlaylists()
            result.onSuccess { playlistsFromApi ->
                playlistsFromApi.forEach { playlist ->
                    val subtitle = "${playlist.songCount ?: 0} canciones"

                    // Construir URL de imagen si la playlist tiene coverArt
                    var imageUrl: String? = null
                    if (playlist.coverArt != null) {
                        val (username, token, salt) = musicRepository.getAuthParams()
                        imageUrl = playlist.getCoverArtUrl(
                            musicRepository.serverUrl!!,
                            username,
                            token,
                            salt,
                            200
                        )
                    }

                    playlists.add(
                        LibraryItem(
                            id = playlist.id,
                            title = playlist.name,
                            subtitle = "Playlist • $subtitle",
                            imageUrl = imageUrl,
                            type = LibraryItemType.PLAYLIST
                        )
                    )

                    // Agregar al mapa de playlists
                    playlistsMap[playlist.id] = playlist
                }
            }.onFailure {
                // Si falla la API, al menos tenemos "Canciones que te gustan"
            }
        } catch (e: Exception) {
            // En caso de error, solo mantener "Canciones que te gustan"
            playlists.clear()
            playlists.add(
                LibraryItem(
                    id = "liked_songs",
                    title = "Canciones que te gustan",
                    subtitle = "Playlist • Tus favoritas",
                    imageUrl = null,
                    type = LibraryItemType.LIKED_SONGS
                )
            )
        }
    }

    private suspend fun loadAlbums() {
        try {
            val result = musicRepository.getStarredAlbums()
            result.onSuccess { albumsFromApi ->
                albums.clear()

                albumsFromApi.forEach { album ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildCoverArtUrl(
                        musicRepository.serverUrl!!,
                        album.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    albums.add(
                        LibraryItem(
                            id = album.id,
                            title = album.name,
                            subtitle = "Álbum • ${album.artist}",
                            imageUrl = imageUrl,
                            type = LibraryItemType.ALBUM
                        )
                    )

                    // Agregar al mapa de álbumes
                    albumsMap[album.id] = album
                }
            }.onFailure {
                albums.clear()
            }
        } catch (e: Exception) {
            albums.clear()
        }
    }

    private suspend fun loadArtists() {
        try {
            val result = musicRepository.getStarredArtists()
            result.onSuccess { artistsFromApi ->
                artists.clear()

                artistsFromApi.forEach { artist ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildArtistImageUrl(
                        musicRepository.serverUrl!!,
                        artist.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    // Construir subtítulo basado en si albumCount está disponible
                    val subtitle = if (artist.albumCount != null && artist.albumCount > 0) {
                        "Artista • ${artist.albumCount} álbumes"
                    } else {
                        "Artista"
                    }

                    artists.add(
                        LibraryItem(
                            id = artist.id,
                            title = artist.name,
                            subtitle = subtitle,
                            imageUrl = imageUrl,
                            type = LibraryItemType.ARTIST
                        )
                    )
                }
            }.onFailure {
                artists.clear()
            }
        } catch (e: Exception) {
            artists.clear()
        }
    }

    private fun buildAllItemsList() {
        allItems.clear()

        // Agregar en orden: playlists, álbumes, artistas
        allItems.addAll(playlists)
        allItems.addAll(albums)
        allItems.addAll(artists)
    }

    private fun filterContent() {
        val filteredItems = when (currentFilter) {
            "all" -> allItems.toList()
            "playlists" -> playlists.toList()
            "albums" -> albums.toList()
            "artists" -> artists.toList()
            else -> allItems.toList()
        }

        if (filteredItems.isEmpty()) {
            showEmptyState()
        } else {
            hideEmptyState()
            libraryAdapter.updateItems(filteredItems)
        }
    }

    private fun handleItemClick(item: LibraryItem) {
        when (item.type) {
            LibraryItemType.PLAYLIST -> {
                // Navegar a playlist específica
                val playlist = playlistsMap[item.id]
                if (playlist != null) {
                    val bundle = Bundle().apply {
                        putString("playlistId", playlist.id)
                        putString("playlistName", playlist.name)
                    }
                    // TODO: Verificar si existe playlistDetailFragment en navigation graph
                    // findNavController().navigate(R.id.playlistDetailFragment, bundle)
                }
            }
            LibraryItemType.ARTIST -> {
                val bundle = Bundle().apply {
                    putString("artistId", item.id)
                    putString("artistName", item.title)
                }
                findNavController().navigate(R.id.artistDetailFragment, bundle)
            }
            LibraryItemType.ALBUM -> {
                // Navegar a detalle de álbum usando el mismo patrón que artistas
                val album = albumsMap[item.id]
                if (album != null) {
                    val bundle = Bundle().apply {
                        putParcelable("album", album)
                    }
                    findNavController().navigate(R.id.albumDetailFragment, bundle)
                }
            }
            LibraryItemType.LIKED_SONGS -> {
                // Navegar a canciones favoritas con animaciones definidas
                findNavController().navigate(R.id.action_library_to_favorites)
            }
        }
    }

    private fun showLoading(show: Boolean) {
        binding.progressBar.visibility = if (show) View.VISIBLE else View.GONE
        binding.rvLibraryItems.visibility = if (show) View.GONE else View.VISIBLE
    }

    private fun showError(message: String) {
        binding.layoutEmpty.visibility = View.VISIBLE
        binding.rvLibraryItems.visibility = View.GONE
        // TODO: Mostrar mensaje de error específico
    }

    private fun showEmptyState() {
        binding.rvLibraryItems.visibility = View.GONE
        binding.layoutEmpty.visibility = View.VISIBLE
    }

    private fun hideEmptyState() {
        binding.layoutEmpty.visibility = View.GONE
        binding.rvLibraryItems.visibility = View.VISIBLE
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}
